const contexts={donor:['Start with a cause you care about.','Choose water, heat or farm resilience. Read a planning brief, tell us what matters to you and ask what evidence is needed before any financial commitment.'],diaspora:['Connect with a place. Understand the route.','Tell us your connection to India and your country or jurisdiction. Explore local needs, recipient eligibility and an appropriate cross-border route before any transfer. No overseas donation route is currently appointed.'],foundation:['Begin with fit, evidence and accountability.','Discuss geography, grant priorities, due diligence and reporting requirements. All three demonstrators are concepts; a complete funding-review dossier and appointed recipient are still pending.'],corporate:['Align local needs with your CSR priorities.','Discuss your geography, project themes, implementation requirements and review process. Project eligibility, partner credentials, budgets and the applicable CSR requirements must be verified before a funding decision.']};
const buttons=[...document.querySelectorAll('[data-donor]')];
function choose(role){if(!contexts[role])return;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.donor===role)));document.getElementById('donor-heading').textContent=contexts[role][0];document.getElementById('donor-copy').textContent=contexts[role][1];document.getElementById('donor-link').href='/?role='+role+'&intent='+(['foundation','corporate','diaspora'].includes(role)?'diligence':'brief')+'#contact';}
buttons.forEach(b=>b.addEventListener('click',()=>choose(b.dataset.donor)));choose(new URLSearchParams(location.search).get('role')||'donor');
